#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin >> t;

    vector<int> arr(t);
    for (int &x : arr)
        cin >> x;

    if (t < 2) {
        cout << arr[0];
        return 0;
    }

    int dif = arr[0] - arr[1];
    bool done = false;

    for (int a = 0; a < t - 1; a++) {
        if (arr[a] - arr[a + 1] != dif) {
            done = true;
            break;
        }
    }

    if (done)
        cout << arr[t - 1];
    else
        cout << arr[t - 1] - dif;

    return 0;
}

